#include "stdafx.h"#include "H_Class.h"static SBlockCreate QOR( "QOR", SH_QOR::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_QOR,W_QOR,52)void SH_QOR::InitParm(){#include "Blocks/QOR.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/QOR_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class QOR_IMPL : public W_QOR{public:  void StepT( SStepCalcParams &dt, int inConsC );};void SH_QOR::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  QOR_IMPL *impl = reinterpret_cast<QOR_IMPL*>(W);  impl->StepT( dt, inConsC );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void QOR_IMPL::StepT( SStepCalcParams &dt, int inConsC ){  if( inConsC <= 0 )    return;  int N = 0;  for( int n = 1; n <= inConsC; n++ )  {    BYTE Actual_IN = IN[n];    if( INPTINVSTS[n] )      Actual_IN = !IN[n];    if( Actual_IN )      ++N;  }  if( N >= K )    OUT = 1;  else    OUT = 0;}